/* @autogenerated */
package net.civeira.phylax.features.oauth.par.application.usecase.resolveparrequest;

import java.time.Duration;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.Optional;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.par.domain.ParRequest;
import net.civeira.phylax.features.oauth.par.domain.exception.ParException;
import net.civeira.phylax.features.oauth.par.domain.gateway.ParBindingGateway;
import net.civeira.phylax.features.oauth.par.domain.gateway.ParRequestGateway;

/**
 * Resolves a {@code request_uri} into its stored authorization parameters — RFC 9126, task 0.14.
 *
 * <ul>
 * <li>The pushed request must be of this tenant and the outer {@code client_id} must be the one it
 * was pushed for.</li>
 * <li>Single use: the first resolution spends it atomically and returns a browser binding; from
 * then on, for the rest of that login ({@code oauth.par.flow-ttl}, 10 minutes by default), only the
 * browser that presents the binding may resolve it again (the login forms post to the same URL).
 * Any other use is {@code invalid_request_uri}.</li>
 * <li>Only the stored parameters count: the caller must ignore the rest of the query.</li>
 * </ul>
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ResolveParRequestUsecase {

  private final ParRequestGateway gateway;
  private final ParBindingGateway bindings;
  @ConfigProperty(name = "oauth.par.flow-ttl", defaultValue = "10m")
  private final Duration flowTtl;

  /**
   * Parameters of a resolved pushed request.
   *
   * @param params stored authorization parameters
   * @param binding browser binding to set, present only on the first resolution
   */
  public record Resolution(Map<String, String> params, Optional<String> binding) {}

  /**
   * Resolves a pushed request.
   *
   * @param requestUri {@code request_uri} of the authorization request
   * @param tenant tenant of the authorization endpoint
   * @param clientId outer {@code client_id} of the authorization request
   * @param binding browser binding presented, if any
   * @return the stored parameters and, on first use, the binding to give the browser
   * @throws ParException invalid_request on a client mismatch, invalid_request_uri otherwise
   */
  public Resolution resolve(String requestUri, String tenant, String clientId,
      Optional<String> binding) {
    ParRequest parRequest =
        gateway.findByUri(requestUri, tenant).orElseThrow(ParException::invalidRequestUri);
    if (clientId == null || !clientId.equals(parRequest.getClientId())) {
      throw ParException.invalidRequest("client_id does not match the pushed request");
    }
    if (parRequest.isExpired()) {
      throw ParException.invalidRequestUri();
    }
    if (parRequest.isUsed()) {
      if (binding.filter(b -> bindings.verify(requestUri, b)).isEmpty()) {
        throw ParException.invalidRequestUri();
      }
      return new Resolution(parRequest.getParams(), Optional.empty());
    }
    if (!gateway.consume(requestUri, tenant, OffsetDateTime.now(ZoneOffset.UTC).plus(flowTtl))) {
      throw ParException.invalidRequestUri();
    }
    return new Resolution(parRequest.getParams(), Optional.of(bindings.bind(requestUri)));
  }

  /**
   * Keeps the parameters of a verified request object (JAR by value) as a pushed request already
   * consumed by this browser, so the login forms that follow use it like any pushed request and the
   * request object itself is used only once (task 3.3).
   *
   * @param tenant tenant of the authorization endpoint
   * @param clientId client of the request object
   * @param params parameters of the request object
   * @return the {@code request_uri} and the binding for the browser
   */
  public Adopted adopt(String tenant, String clientId, Map<String, String> params) {
    ParRequest parRequest = ParRequest.create(tenant, clientId, params);
    gateway.store(parRequest);
    if (!gateway.consume(parRequest.getRequestUri(), tenant,
        OffsetDateTime.now(ZoneOffset.UTC).plus(flowTtl))) {
      throw ParException.invalidRequestUri();
    }
    return new Adopted(parRequest.getRequestUri(), bindings.bind(parRequest.getRequestUri()));
  }

  /**
   * A request object kept as a consumed pushed request.
   *
   * @param requestUri its {@code request_uri}
   * @param binding binding for the browser
   */
  public record Adopted(String requestUri, String binding) {}

  /**
   * Remaining life of a login that consumed a pushed request, for the binding cookie.
   *
   * @return the flow lifetime
   */
  public Duration flowTtl() {
    return flowTtl;
  }
}
